1	import RichText from '@/components/RichText';
2	import { Books, Clock } from '@/components/icons';
3	
4	/*
5	 * Documents → Book tab. Renders the founder's memoir-in-progress
6	 * snippets — a small section that lives alongside Stories and Blogs
7	 * but is intentionally lower-key. Per teww-cms-content-update-v2.md,
8	 * the founder's voice belongs in a contained place, not promoted on
9	 * the home page or main archive.
10	 */
11	
12	export interface BookChapter {
13	  id?: string;
14	  num?: string;
15	  title?: string;
16	  readTime?: string;
17	  status?: string;
18	  snippet?: string;
19	  slug?: string;
20	  visible?: boolean;
21	}
22	
23	export interface BookContent {
24	  eyebrow?: string;
25	  title?: string;
26	  subtitle?: string;
27	  intro?: string;
28	  chapters?: BookChapter[];
29	}
30	
31	export default function BookTab({ book }: { book: BookContent }) {
32	  const chapters = (book.chapters || []).filter((c) => c?.visible !== false);
33	
34	  return (
35	    <section className="section">
36	      <div className="section-inner">
37	        <div className="book-intro">
38	          <div className="section-eyebrow">{book.eyebrow || 'From the Book'}</div>
39	          <RichText as="h2" className="section-title book-title" html={book.title || 'The Book.'} />
40	          {book.subtitle ? (
41	            <div className="book-byline">
42	              <Books size="1em" aria-hidden="true" />
43	              <span>{book.subtitle}</span>
44	            </div>
45	          ) : null}
46	          {book.intro ? <p className="book-intro-text">{book.intro}</p> : null}
47	        </div>
48	
49	        {chapters.length > 0 ? (
50	          <ol className="book-chapters" role="list">
51	            {chapters.map((c, i) => (
52	              <li key={c.id || i} className="book-chapter">
53	                <div className="book-chapter-meta">
54	                  <span className="book-chapter-num" aria-hidden="true">
55	                    {c.num || String(i + 1).padStart(2, '0')}
56	                  </span>
57	                  {c.readTime ? (
58	                    <span className="book-chapter-readtime">
59	                      <Clock size="1em" aria-hidden="true" /> {c.readTime}
60	                    </span>
61	                  ) : null}
62	                </div>
63	                <h3 className="book-chapter-title">{c.title || ''}</h3>
64	                {c.snippet ? <p className="book-chapter-snippet">{c.snippet}</p> : null}
65	                {c.status ? (
66	                  <div className="book-chapter-status">{c.status}</div>
67	                ) : null}
68	              </li>
69	            ))}
70	          </ol>
71	        ) : (
72	          <p style={{ color: 'var(--fg-muted)' }}>Chapters arriving soon.</p>
73	        )}
74	
75	        <p className="book-foot">
76	          The book is in progress. Excerpts will publish here as chapters
77	          finalise — subscribe via the newsletter on the Research tab to be
78	          notified.
79	        </p>
80	      </div>
81	    </section>
82	  );
83	}
