1	import { Suspense } from 'react';
2	import { getContent, visibleSorted } from '@/lib/cms/db';
3	import RichText from '@/components/RichText';
4	import { SkeletonHero } from '@/components/Skeleton';
5	import Subnav from '@/components/site/Subnav';
6	import DocCard from '@/components/documents/DocCard';
7	import FilterableBlogGrid from '@/components/documents/FilterableBlogGrid';
8	import NewsletterForm from '@/components/documents/NewsletterForm';
9	import FeaturedStory from '@/components/documents/FeaturedStory';
10	import BookTab, { type BookContent } from '@/components/documents/BookTab';
11	import { pageMetadata, readSeoOverrides } from '@/lib/seo';
12	
13	export const revalidate = 3600;
14	
15	export async function generateMetadata() {
16	  const content = await getContent();
17	  const o = readSeoOverrides(content, '/documents');
18	  const d = content?.documents || {};
19	  return pageMetadata({
20	    title: o.title || 'Documents — Third Eye Worldwide',
21	    description: o.description || d.heroSub || 'Applied research, stories, and long-form writing from the TEWW team and community.',
22	    path: '/documents',
23	    image: o.image,
24	    noindex: o.noindex,
25	  });
26	}
27	
28	// eslint-disable-next-line @typescript-eslint/no-explicit-any, @typescript-eslint/no-unused-vars
29	function chunk<T>(arr: T[], size: number): T[][] {
30	  const out: T[][] = [];
31	  for (let i = 0; i < arr.length; i += size) out.push(arr.slice(i, i + size));
32	  return out;
33	}
34	
35	// eslint-disable-next-line @typescript-eslint/no-explicit-any
36	function BlogsTab({ blogs, cats }: { blogs: any[]; cats: string[] }) {
37	  return (
38	    <>
39	      <section className="section">
40	        <div className="section-inner">
41	          <FilterableBlogGrid blogs={blogs} cats={cats} />
42	        </div>
43	      </section>
44	      <section className="section section-alt">
45	        <div className="section-inner">
46	          <NewsletterForm />
47	        </div>
48	      </section>
49	    </>
50	  );
51	}
52	
53	// eslint-disable-next-line @typescript-eslint/no-explicit-any
54	function StoriesTab({ stories, fs }: { stories: any[]; fs: any }) {
55	  return (
56	    <section className="section">
57	      <div className="section-inner">
58	        <div className="section-heading left" style={{ maxWidth: 720, marginBottom: 32 }}>
59	          <div className="section-eyebrow">Stories</div>
60	          <h2 className="section-title">Voices from our community</h2>
61	          <p className="section-subtitle">
62	            Real people, real independence. These are the stories that remind us why the work matters.
63	          </p>
64	        </div>
65	
66	        <FeaturedStory fs={fs} />
67	
68	        <h3 className="stories-list-heading">More stories</h3>
69	        {stories.length > 0 ? (
70	          <div className="doc-grid">
71	            {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
72	            {stories.map((s: any) => <DocCard key={s.id || s.title} doc={s} defaultKind="story" />)}
73	          </div>
74	        ) : (
75	          <p style={{ color: 'var(--fg-muted)' }}>No stories yet.</p>
76	        )}
77	
78	        {stories.length > 6 ? (
79	          <div style={{ display: 'flex', justifyContent: 'center', marginTop: 48 }}>
80	            <button type="button" className="btn-secondary">Load more stories</button>
81	          </div>
82	        ) : null}
83	      </div>
84	    </section>
85	  );
86	}
87	
88	export default function DocumentsPage() {
89	  return (
90	    <Suspense fallback={<SkeletonHero />}>
91	      <DocumentsPageContent />
92	    </Suspense>
93	  );
94	}
95	
96	async function DocumentsPageContent() {
97	  // DB hiccup → empty sections, not a 500. See app/page.tsx.
98	  let content = null;
99	  try {
100	    content = await getContent();
101	  } catch {
102	    // fall through to empty-content render
103	  }
104	  const d = content?.documents || {};
105	  const blogs = visibleSorted(d.blogs || []);
106	  const stories = visibleSorted(d.stories || []);
107	  const fs = d.featuredStory || {};
108	  const book = (d.book || {}) as BookContent;
109	  const cats = Array.from(new Set(blogs.map((b) => (b as { cat?: string }).cat).filter(Boolean))) as string[];
110	  const tabs: { id: string; label: string; content: React.ReactNode }[] = [
111	    { id: 'blogs', label: 'Research', content: <BlogsTab blogs={blogs} cats={cats} /> },
112	    { id: 'stories', label: 'Stories', content: <StoriesTab stories={stories} fs={fs} /> },
113	  ];
114	  // Only mount the Book tab if the CMS has any chapters configured —
115	  // keeps it from showing as an empty section on a fresh install.
116	  if (book?.chapters && book.chapters.length > 0) {
117	    tabs.push({ id: 'book', label: 'Book', content: <BookTab book={book} /> });
118	  }
119	
120	  return (
121	    <>
122	      <div className="page-hero">
123	        <div className="page-hero-inner">
124	          <div className="section-eyebrow">{d.heroEyebrow || 'Documents'}</div>
125	          <RichText as="h1" html={d.heroTitle || 'Read deeper.'} />
126	          {d.heroSub ? <p>{d.heroSub}</p> : null}
127	        </div>
128	      </div>
129	
130	      <Subnav
131	        page="documents"
132	        ariaLabel="Documents sections"
133	        defaultTab="blogs"
134	        tabs={tabs}
135	      />
136	    </>
137	  );
138	}
