1	'use client';
2	
3	import { useState } from 'react';
4	import DocCard from '@/components/documents/DocCard';
5	import { cn } from '@/lib/utils';
6	
7	/*
8	 * Filter pills + card grid for the blogs subpage.
9	 * `cats` is the unique list of blog categories; 'all' is injected.
10	 *
11	 * Uses a single .doc-grid with auto-fit tracks so cards reflow
12	 * cleanly as the list is filtered (no JS chunking into fixed rows).
13	 */
14	export interface Blog {
15	  id?: string;
16	  title?: string;
17	  cat?: string;
18	  excerpt?: string;
19	  [k: string]: unknown;
20	}
21	export interface FilterableBlogGridProps {
22	  blogs: Blog[];
23	  cats: string[];
24	}
25	
26	export default function FilterableBlogGrid({ blogs, cats }: FilterableBlogGridProps) {
27	  const [filter, setFilter] = useState('all');
28	  const visible = filter === 'all' ? blogs : blogs.filter((b: Blog) => b.cat === filter);
29	
30	  return (
31	    <>
32	      {cats.length > 0 ? (
33	        <div className="filter-bar" data-filter-group="blogs">
34	          <div className="filter-label">Topic</div>
35	          <button
36	            type="button"
37	            className={cn('filter-pill', { active: filter === 'all' })}
38	            aria-pressed={filter === 'all'}
39	            onClick={() => setFilter('all')}
40	          >
41	            All
42	          </button>
43	          {cats.map((c: string) => (
44	            <button
45	              key={c}
46	              type="button"
47	              className={cn('filter-pill', { active: filter === c })}
48	              aria-pressed={filter === c}
49	              onClick={() => setFilter(c)}
50	            >
51	              {c.charAt(0).toUpperCase() + c.slice(1)}
52	            </button>
53	          ))}
54	        </div>
55	      ) : null}
56	
57	      {blogs.length === 0 ? (
58	        <p className="grid-empty">No research published yet. Check back soon.</p>
59	      ) : visible.length === 0 ? (
60	        <p className="grid-empty">No research matches this filter.</p>
61	      ) : (
62	        <div className="doc-grid">
63	          {visible.map((b: Blog) => <DocCard key={b.id || b.title} doc={b} defaultKind="blog" />)}
64	        </div>
65	      )}
66	    </>
67	  );
68	}
