1	'use client';
2	
3	import { useState, type FormEvent } from 'react';
4	import { Check, PaperPlaneTilt } from '@/components/icons';
5	
6	/*
7	 * Newsletter signup on /documents#blogs. Client-only because it
8	 * tracks submit state; not wired to a backend (the original was
9	 * also client-only — it just toggled button text on submit).
10	 */
11	export default function NewsletterForm() {
12	  const [subscribed, setSubscribed] = useState(false);
13	  const [email, setEmail] = useState('');
14	
15	  function handleSubmit(e: FormEvent<HTMLFormElement>) {
16	    e.preventDefault();
17	    if (!email) return;
18	    // TODO: wire to /api/cms/submissions/newsletter once it exists.
19	    setSubscribed(true);
20	  }
21	
22	  return (
23	    <div className="newsletter-card">
24	      <div>
25	        <div className="section-eyebrow" style={{ marginBottom: 10 }}>Newsletter</div>
26	        <h2 className="newsletter-title">Twice a month. No spam.</h2>
27	        <p className="newsletter-body">
28	          Research summaries, new tools, and stories from the field — delivered in plain
29	          text, screen-reader-optimised, with a one-click unsubscribe.
30	        </p>
31	      </div>
32	      <form className="newsletter-form" onSubmit={handleSubmit}>
33	        <input
34	          type="email"
35	          placeholder="you@example.com"
36	          required
37	          value={email}
38	          onChange={(e) => setEmail(e.target.value)}
39	          className="newsletter-input"
40	          aria-label="Email address"
41	          disabled={subscribed}
42	        />
43	        <button
44	          type="submit"
45	          className="btn-primary"
46	          style={{ justifyContent: 'center' }}
47	          disabled={subscribed}
48	        >
49	          {subscribed ? (
50	            <><Check size="1em" aria-hidden="true" /> Subscribed</>
51	          ) : (
52	            <><PaperPlaneTilt size="1em" aria-hidden="true" /> Subscribe</>
53	          )}
54	        </button>
55	      </form>
56	    </div>
57	  );
58	}
