1	import Link from 'next/link';
2	
3	/*
4	 * Documents blog/story tile. Renders as a full-card link.
5	 *
6	 * `doc` shape: { title, desc, heroType, tagClass, tagLabel, cat,
7	 *                author, initials, meta, readTime, extra }.
8	 * `defaultKind` decides the link target when tagClass isn't set.
9	 */
10	interface Doc {
11	  tagClass?: string;
12	  heroType?: string;
13	  tagLabel?: string;
14	  extra?: string;
15	  cat?: string;
16	  title?: string;
17	  desc?: string;
18	  author?: string;
19	  initials?: string;
20	  meta?: string;
21	  readTime?: string;
22	  id?: string;
23	}
24	interface DocCardProps {
25	  doc?: Doc;
26	  defaultKind?: 'blog' | 'story';
27	}
28	
29	export default function DocCard({ doc, defaultKind = 'blog' }: DocCardProps) {
30	  const {
31	    tagClass, heroType, tagLabel, extra, cat,
32	    title, desc, author, initials = 'TE', meta, readTime,
33	  } = doc || {};
34	
35	  const kind = tagClass === 'story' ? 'story' : 'blog';
36	  const href = kind === 'story' ? '/story-detail' : '/blog-detail';
37	  const displayHero = heroType || (kind === 'story' ? 'type-story' : 'type-blog');
38	  const displayTagClass = tagClass || defaultKind;
39	  const displayTagLabel = tagLabel || (defaultKind === 'story' ? 'Story' : 'Research');
40	
41	  return (
42	    <Link
43	      className={`doc-card ${extra || ''}`.trim()}
44	      href={href}
45	      aria-label={`Read: ${title}`}
46	      data-cat={cat || ''}
47	    >
48	      <div className={`doc-hero ${displayHero}`}>
49	        <div>
50	          <span className={`cat-tag ${displayTagClass}`}>{displayTagLabel}</span>
51	          <h3>{title}</h3>
52	        </div>
53	      </div>
54	      <div className="doc-body">
55	        <p>{desc}</p>
56	        <div className="doc-meta">
57	          <div className="doc-author">
58	            <div className="avatar">{initials}</div>
59	            <span>{author || ''}</span>
60	          </div>
61	          <span className="sep">·</span>
62	          <span>{meta || readTime || ''}</span>
63	        </div>
64	      </div>
65	    </Link>
66	  );
67	}
