1	/* ── DOCUMENTS / BLOG / STORIES ─────── */
2	/*
3	 * Doc grid (stories/blogs tiles): auto-fit so any extra cards wrap to
4	 * the next row cleanly, with a sensible minimum per card so the hero
5	 * titles never collapse into one-word-per-line columns. The featured
6	 * card opts in to spanning two tracks for visual weight on home + the
7	 * documents archive.
8	 */
9	.doc-grid {
10	  display: grid;
11	  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
12	  gap: 24px;
13	}
14	.doc-grid > .doc-card.featured { grid-column: span 2; }
15	@media (max-width: 720px) {
16	  .doc-grid > .doc-card.featured { grid-column: auto; }
17	}
18	
19	/* ── BOOK TAB (Documents → Book) ─────────────────────────────
20	   Founder's memoir-in-progress: low-key, list-based layout, no card
21	   imagery. Per the v2 content update — quiet placement, off the main
22	   archive. */
23	.book-intro { max-width: 720px; margin: 0 auto 48px; text-align: left; }
24	.book-intro .section-eyebrow { margin-bottom: 14px; }
25	.book-title { font-family: var(--font-display); font-size: clamp(1.85rem, 3vw, 2.5rem); font-weight: 700; letter-spacing: -.02em; line-height: 1.15; color: var(--fg); margin-bottom: 14px; text-wrap: balance; }
26	.book-byline { display: inline-flex; align-items: center; gap: 8px; font-family: var(--font-display); font-size: .9rem; font-weight: 600; color: var(--brand); margin-bottom: 18px; }
27	.book-intro-text { font-size: 1.02rem; line-height: 1.7; color: var(--fg-muted); }
28	
29	.book-chapters { list-style: none; padding: 0; margin: 0; max-width: 760px; counter-reset: book; }
30	.book-chapter {
31	  counter-increment: book;
32	  padding: 28px 0;
33	  border-top: 1px solid var(--border);
34	}
35	.book-chapter:last-child { border-bottom: 1px solid var(--border); }
36	.book-chapter-meta {
37	  display: flex; align-items: center; gap: 18px;
38	  font-family: var(--font-display); font-size: .76rem; font-weight: 700;
39	  letter-spacing: .14em; text-transform: uppercase;
40	  color: var(--fg-subtle);
41	  margin-bottom: 8px;
42	}
43	.book-chapter-num { color: var(--accent); }
44	.book-chapter-readtime { display: inline-flex; align-items: center; gap: 6px; }
45	.book-chapter-title {
46	  font-family: var(--font-display); font-size: 1.4rem; font-weight: 700;
47	  letter-spacing: -.015em; color: var(--fg); line-height: 1.25;
48	  margin-bottom: 10px; text-wrap: balance;
49	}
50	.book-chapter-snippet {
51	  font-size: 1rem; line-height: 1.65; color: var(--fg-muted);
52	  max-width: 64ch; margin-bottom: 12px;
53	}
54	.book-chapter-status {
55	  display: inline-block;
56	  font-family: var(--font-display); font-size: .72rem; font-weight: 700;
57	  letter-spacing: .1em; text-transform: uppercase;
58	  color: var(--fg-subtle);
59	  padding: 4px 10px; border: 1px solid var(--border);
60	  border-radius: var(--radius-full);
61	  background: var(--bg-elevated);
62	}
63	.book-foot {
64	  max-width: 760px; margin: 36px 0 0;
65	  font-size: .92rem; line-height: 1.65;
66	  color: var(--fg-muted);
67	}
68	
69	.doc-card {
70	  background: var(--bg-elevated);
71	  border: 1px solid var(--border);
72	  border-radius: var(--radius-lg);
73	  overflow: hidden;
74	  box-shadow: var(--shadow-sm);
75	  transition: box-shadow .2s, transform .2s;
76	  display: flex;
77	  flex-direction: column;
78	  min-width: 0; /* let the grid shrink this below intrinsic content */
79	  text-decoration: none;
80	  color: inherit;
81	}
82	.doc-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
83	.doc-hero { aspect-ratio: 16/10; display: flex; align-items: flex-end; padding: 28px; position: relative; overflow: hidden; min-width: 0; }
84	.doc-card.featured .doc-hero { aspect-ratio: 16/9; }
85	.doc-card .cat-tag { font-family: var(--font-display); font-size: .7rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; padding: 4px 10px; border-radius: var(--radius-full); align-self: flex-start; margin-bottom: 10px; }
86	.doc-hero.type-blog { background: linear-gradient(135deg, var(--brand) 0%, #1349d4 100%); color: #fff; }
87	.doc-hero.type-story { background: linear-gradient(135deg, var(--accent) 0%, #c04c18 100%); color: #fff; }
88	.doc-hero.type-report { background: linear-gradient(135deg, #0d0407 0%, #1e1a2e 100%); color: #fff; }
89	.doc-hero.type-policy { background: linear-gradient(135deg, #eaeaf5 0%, #d4d4e8 100%); color: var(--fg); }
90	.doc-hero.type-tutorial { background: linear-gradient(135deg, #eef3ff 0%, #d6e4ff 100%); color: var(--fg); }
91	.doc-hero.type-story2 { background: linear-gradient(135deg, #f07a3d 0%, #ffaa5c 100%); color: #fff; }
92	.doc-hero h3 {
93	  font-family: var(--font-display);
94	  font-size: 1.35rem;
95	  font-weight: 700;
96	  line-height: 1.15;
97	  letter-spacing: -.02em;
98	  color: inherit;
99	  text-wrap: pretty;
100	  overflow-wrap: break-word;
101	  hyphens: auto;
102	}
103	.doc-card.featured .doc-hero h3 { font-size: 1.75rem; }
104	.doc-body { padding: 18px 22px 22px; display: flex; flex-direction: column; gap: 10px; flex: 1; min-width: 0; }
105	.doc-body p {
106	  font-size: .88rem;
107	  color: var(--fg-muted);
108	  line-height: 1.55;
109	  flex: 1;
