3	import { useEffect, useState } from 'react';
4	
5	/*
6	 * Generic tab controller used by routes with a subnav (About, Media,
7	 * Documents, etc). Pass the page key + an array of
8	 * `{ id, label, content }` tabs. Content can be any React node
9	 * including server components.
10	 *
11	 * Active tab initializes from the URL hash (e.g. /about#team) only,
12	 * so a fresh visit to /about always lands on the `defaultTab`.
13	 * Hash-based persistence is enough for sharing/back-forward; we
14	 * deliberately don't restore from localStorage anymore because it led
15	 * to confusing returning-visitor state ("I expected Overview, got Team").
16	 */
17	import type { ReactNode } from 'react';
18	
19	export interface SubnavTab {
20	  id: string;
21	  label: string;
22	  content: ReactNode;
23	}
24	
25	interface SubnavProps {
26	  page: string;
27	  tabs: SubnavTab[];
28	  defaultTab?: string;
29	  ariaLabel?: string;
30	}
31	
32	export default function Subnav({ page, tabs, defaultTab, ariaLabel }: SubnavProps) {
33	  const fallbackTab = defaultTab || tabs?.[0]?.id || '';
34	  const [active, setActive] = useState<string>(fallbackTab);
35	
36	  useEffect(() => {
37	    if (typeof window === 'undefined') return;
38	    const hash = window.location.hash.slice(1);
39	    if (hash && tabs.some((t) => t.id === hash)) setActive(hash);
40	    // eslint-disable-next-line react-hooks/exhaustive-deps
41	  }, []);
42	
43	  function activate(id: string) {
44	    setActive(id);
45	    try {
46	      const url = new URL(window.location.href);
47	      url.hash = id;
48	      window.history.replaceState({}, '', url.toString());
49	    } catch {}
50	  }
51	
52	  return (
53	    <>
54	      <nav className="subnav" aria-label={ariaLabel || `${page} sections`}>
55	        <div className="subnav-inner" role="tablist">
56	          {tabs.map((t) => (
57	            <button
58	              key={t.id}
59	              id={`subnav-tab-${t.id}`}
60	              type="button"
61	              role="tab"
62	              aria-selected={active === t.id}
63	              aria-controls={`subnav-panel-${t.id}`}
64	              tabIndex={active === t.id ? 0 : -1}
65	              data-sub={t.id}
66	              className={active === t.id ? 'active' : ''}
67	              onClick={() => activate(t.id)}
68	            >
69	              {t.label}
70	            </button>
71	          ))}
72	        </div>
73	      </nav>
74	
75	      {tabs.map((t) => (
76	        <div
77	          key={t.id}
78	          id={`subnav-panel-${t.id}`}
79	          role="tabpanel"
80	          aria-labelledby={`subnav-tab-${t.id}`}
81	          hidden={active !== t.id}
82	          data-sub={t.id}
83	          className={`subpage${active === t.id ? ' active' : ''}`}
84	        >
85	          {t.content}
86	        </div>
87	      ))}
88	    </>
89	  );
90	}
