/*
 * RichText — renders CMS-authored strings that may contain trusted
 * inline HTML (<em>, <br>, <strong>, <i>, etc). Content source is the
 * admin-authenticated CMS, but we still sanitize at render time as
 * defense-in-depth: a compromised admin account, a SQL-level injection,
 * or a future migration that pulls user-submitted text into a "rich"
 * field would otherwise turn directly into XSS.
 *
 * Sanitization uses sanitize-html (pure-JS htmlparser2 backend, no
 * jsdom / DOM polyfill). The previous library, isomorphic-dompurify,
 * pulled in jsdom -> html-encoding-sniffer -> @exodus/bytes (ESM-only),
 * which broke `next build` on Node < 20.19 with ERR_REQUIRE_ESM. The
 * security model is unchanged — strict allowlist of inline formatting
 * tags, single `class` attribute, everything else stripped.
 *
 * Use for fields the CMS marks as "rich" (e.g. heroTitle, pullQuote).
 * For plain-text fields, pass the string as a normal JSX child — React
 * will escape it automatically.
 */
import type { ElementType, HTMLAttributes } from 'react';
import sanitizeHtml from 'sanitize-html';

// Tags allowed inside CMS rich fields. Anything outside this list is
// stripped (the inner text is preserved). Keep this list as small as
// possible — every additional tag widens the XSS surface.
const ALLOWED_TAGS = ['em', 'i', 'strong', 'b', 'br', 'span', 'sup', 'sub', 'mark', 'u'];

// Only `class` is allowed, and only on tags we already whitelisted.
// sanitize-html keys allowedAttributes by tag name; the '*' wildcard
// applies the rule uniformly. URL-bearing attrs (href, src, srcdoc)
// are absent by design — none of the allowed tags need them, and
// omitting them avoids URL-scheme spoofing (javascript:, data:, etc).
const ALLOWED_ATTRIBUTES: sanitizeHtml.IOptions['allowedAttributes'] = {
  '*': ['class'],
};

const SANITIZE_OPTIONS: sanitizeHtml.IOptions = {
  allowedTags: ALLOWED_TAGS,
  allowedAttributes: ALLOWED_ATTRIBUTES,
  // Disable schemes that could smuggle JS even if a URL attr ever got
  // added in the future. Empty array == no protocols permitted at all.
  allowedSchemes: [],
  allowedSchemesByTag: {},
  // Stripped tags lose their wrapping but the inner text is kept; this
  // matches the previous DOMPurify default behavior so existing CMS
  // content renders identically.
  disallowedTagsMode: 'discard',
  // Don't try to "fix" malformed HTML by re-parsing — operate on the
  // raw token stream. Slightly faster and more predictable.
  parseStyleAttributes: false,
};

function sanitize(html: string): string {
  return sanitizeHtml(html, SANITIZE_OPTIONS);
}

interface RichTextProps extends Omit<HTMLAttributes<HTMLElement>, 'dangerouslySetInnerHTML'> {
  as?: ElementType;
  html?: string | null;
  className?: string;

