async function DocumentsPageContent() {
  // DB hiccup → empty sections, not a 500. See app/page.tsx.
  let content = null;
  try {
    content = await getContent();
  } catch {
    // fall through to empty-content render
  }
  const d = content?.documents || {};
  const blogs = visibleSorted(d.blogs || []);
  const stories = visibleSorted(d.stories || []);
  const fs = d.featuredStory || {};
  const book = (d.book || {}) as BookContent;
  const cats = Array.from(new Set(blogs.map((b) => (b as { cat?: string }).cat).filter(Boolean))) as string[];
  const tabs: { id: string; label: string; content: React.ReactNode }[] = [
    { id: 'blogs', label: 'Research', content: <BlogsTab blogs={blogs} cats={cats} /> },
    { id: 'stories', label: 'Stories', content: <StoriesTab stories={stories} fs={fs} /> },
  ];
  // Only mount the Book tab if the CMS has any chapters configured —
  // keeps it from showing as an empty section on a fresh install.
  if (book?.chapters && book.chapters.length > 0) {
    tabs.push({ id: 'book', label: 'Book', content: <BookTab book={book} /> });
  }

  return (
    <>
      <div className="docs-hero">
        {/* Echo-ripple motif — sound made visible. Decorative only. */}
        <div className="docs-hero-ripple" aria-hidden="true">
          <span></span><span></span><span></span>
        </div>
        <div className="docs-hero-inner">
          <div className="section-eyebrow">{d.heroEyebrow || 'Documents'}</div>
          <RichText as="h1" className="docs-hero-title" html={d.heroTitle || 'Read deeper.'} />
          {d.heroSub ? <p className="docs-hero-sub">{d.heroSub}</p> : null}
        </div>
      </div>

      <Subnav
        page="documents"
        ariaLabel="Documents sections"
        defaultTab="blogs"
        tabs={tabs}
      />
    </>
  );
}

import Link from 'next/link';
import RichText from '@/components/RichText';

/*
 * Documents editorial row — a research paper or community story
 * rendered as a full-row link in the night archive (Sight Beyond
 * Sight). Formerly a gradient card; the row keeps every CMS field
 * the card rendered and adds `date`/`role`, which the CMS carries
 * but the card silently dropped.
 *
 * `doc` shape: { title, desc, heroType, tagClass, tagLabel, cat,
 *                author, initials, role, date, meta, readTime, extra }.
 * `defaultKind` decides the link target when tagClass isn't set.
 */
interface Doc {
  tagClass?: string;
  heroType?: string;
  tagLabel?: string;
  extra?: string;
  cat?: string;
  title?: string;
  desc?: string;
  author?: string;
  initials?: string;
  role?: string;
  date?: string;
  meta?: string;
  readTime?: string;
  id?: string;
}
interface DocCardProps {
  doc?: Doc;
  defaultKind?: 'blog' | 'story';
}

export default function DocCard({ doc, defaultKind = 'blog' }: DocCardProps) {
  const {
    tagClass, tagLabel, extra, cat,
    title, desc, author, initials = 'TE', role, date, meta, readTime,
  } = doc || {};

  const kind = tagClass === 'story' ? 'story' : 'blog';
  const href = kind === 'story' ? '/story-detail' : '/blog-detail';
  const displayTagLabel = tagLabel || (defaultKind === 'story' ? 'Story' : 'Research');
  const plainTitle = (title || '').replace(/<[^>]+>/g, '');

  return (
    <Link
      className={`doc-row ${extra || ''}`.trim()}
      href={href}
      aria-label={`Read: ${plainTitle}`}
      data-cat={cat || ''}
      role="listitem"
    >
      <div className="doc-row-side">
        <span className="doc-row-tag">{displayTagLabel}</span>
        {date ? <span className="doc-row-date">{date}</span> : null}
      </div>
      <div className="doc-row-main">
        <RichText as="h3" className="doc-row-title" html={title || ''} />
        {desc ? <p className="doc-row-desc">{desc}</p> : null}
        <div className="doc-row-meta">
          <span className="doc-row-avatar" aria-hidden="true">{initials}</span>
          <span className="doc-row-author">
            {author || ''}
            {role ? <span className="doc-row-role"> · {role}</span> : null}
          </span>
          {(meta || readTime) ? (
            <span className="doc-row-read">{meta || readTime}</span>
          ) : null}
        </div>
      </div>
      <span className="doc-row-arrow" aria-hidden="true">→</span>
    </Link>
  );
}

