'use client';

import { useState } from 'react';
import DocCard from '@/components/documents/DocCard';
import { cn } from '@/lib/utils';

/*
 * Topic filter pills + editorial row list for the Research tab.
 * `cats` is the unique list of blog categories; 'all' is injected.
 * Rows reflow as a simple vertical list, so filtering never leaves
 * orphaned grid tracks.
 */
export interface Blog {
  id?: string;
  title?: string;
  cat?: string;
  excerpt?: string;
  [k: string]: unknown;
}
export interface FilterableBlogGridProps {
  blogs: Blog[];
  cats: string[];
}

export default function FilterableBlogGrid({ blogs, cats }: FilterableBlogGridProps) {
  const [filter, setFilter] = useState('all');
  const visible = filter === 'all' ? blogs : blogs.filter((b: Blog) => b.cat === filter);

  return (
    <>
      <div className="section-heading left docs-research-heading">
        <div className="section-eyebrow">Research</div>
        <h2 className="section-title">The science behind the work</h2>
      </div>

      {cats.length > 0 ? (
        <div className="filter-bar docs-filter" data-filter-group="blogs">
          <div className="filter-label">Topic</div>
          <button
            type="button"
            className={cn('filter-pill', { active: filter === 'all' })}
            aria-pressed={filter === 'all'}
            onClick={() => setFilter('all')}
          >
            All
          </button>
          {cats.map((c: string) => (
            <button
              key={c}
              type="button"
              className={cn('filter-pill', { active: filter === c })}
              aria-pressed={filter === c}
              onClick={() => setFilter(c)}
            >
              {c.charAt(0).toUpperCase() + c.slice(1)}
            </button>
          ))}
        </div>
      ) : null}

      {blogs.length === 0 ? (
        <p className="grid-empty">No research published yet. Check back soon.</p>
      ) : visible.length === 0 ? (
        <p className="grid-empty">No research matches this filter.</p>
      ) : (
        <div className="doc-rows" role="list">
          {visible.map((b: Blog) => <DocCard key={b.id || b.title} doc={b} defaultKind="blog" />)}
        </div>
      )}
    </>
  );
}

import Link from 'next/link';
import RichText from '@/components/RichText';
