/*
 * Featured-story editorial block at the top of /documents#stories —
 * a full-width night statement framed by gold hairlines. Carries the
 * open-call copy, so the pull-quote leads at display size.
 *
 * `fs` shape: { eyebrow, pullQuote, title, desc, author, authorRole,
 * role, initials }. (`authorRole` is the documented field; some CMS
 * rows carry `role` instead, so we accept both.)
 */
interface FeaturedStoryData {
  eyebrow?: string;
  pullQuote?: string;
  title?: string;
  desc?: string;
  author?: string;
  authorRole?: string;
  role?: string;
  initials?: string;
}
export default function FeaturedStory({ fs }: { fs?: FeaturedStoryData }) {
  if (!fs?.title) return null;
  const { eyebrow = 'Featured Story', pullQuote = '', title, desc = '', author = '', initials = 'TE' } = fs;
  const authorRole = fs.authorRole || fs.role || '';
  return (
    <article className="featured-story">
      <div className="fs-eyebrow">{eyebrow}</div>
      {pullQuote ? (
        <RichText as="blockquote" className="fs-quote" html={pullQuote} />
      ) : null}
      <div className="fs-body">
        <RichText as="h3" className="fs-title" html={title} />
        <p className="fs-desc">{desc}</p>
        <div className="fs-author-row">
          <div className="fs-author-avatar" aria-hidden="true">{initials}</div>
          <div>
            <div className="fs-author-name">{author}</div>
            {authorRole ? <div className="fs-author-role">{authorRole}</div> : null}
          </div>
          <Link href="/story-detail" className="btn-primary fs-read-btn">
            Read <ArrowRight size="1em" aria-hidden="true" />
          </Link>
        </div>
      </div>
    </article>
  );
}

import RichText from '@/components/RichText';
import { Books, Clock } from '@/components/icons';

/*
 * Documents → Book tab. The founder's memoir-in-progress, set as an
 * actual book: a title page (eyebrow, Literata title, byline, intro
 * set large in Literata) followed by a chapter index — oversized
 * Literata numerals, italic chapter titles, read-times, and a quiet
 * gold-dashed "Excerpt coming soon" state. Per
 * teww-cms-content-update-v2.md the founder's voice stays contained
 * here, off the home page and main archive.
 */

export interface BookChapter {
  id?: string;
  num?: string;
  title?: string;
  readTime?: string;
  status?: string;
  snippet?: string;
  slug?: string;
  visible?: boolean;
}

export interface BookContent {
  eyebrow?: string;
  title?: string;
  subtitle?: string;
  intro?: string;
  chapters?: BookChapter[];
}

export default function BookTab({ book }: { book: BookContent }) {
  const chapters = (book.chapters || []).filter((c) => c?.visible !== false);

  return (
    <section className="section book-section">
      <div className="section-inner">
        {/* Title page */}
        <div className="book-intro">
          <div className="section-eyebrow">{book.eyebrow || 'From the Book'}</div>
          <RichText as="h2" className="book-title" html={book.title || 'The Book.'} />
          {book.subtitle ? (
            <div className="book-byline">
              <Books size="1em" aria-hidden="true" />
              <span>{book.subtitle}</span>
            </div>
          ) : null}
          {book.intro ? <p className="book-intro-text">{book.intro}</p> : null}
        </div>

        {chapters.length > 0 ? (
          <ol className="book-chapters" role="list">
            {chapters.map((c, i) => (
              <li key={c.id || i} className="book-chapter">
                <span className="book-chapter-num" aria-hidden="true">
                  {c.num || String(i + 1).padStart(2, '0')}
                </span>
                <div className="book-chapter-body">
                  <div className="book-chapter-head">
                    <h3 className="book-chapter-title">{c.title || ''}</h3>
                    {c.readTime ? (
                      <span className="book-chapter-readtime">
                        <Clock size="1em" aria-hidden="true" /> {c.readTime}
                      </span>
                    ) : null}
                  </div>
                  {c.snippet ? <p className="book-chapter-snippet">{c.snippet}</p> : null}
                  {c.status ? (
                    <div className="book-chapter-status">{c.status}</div>
                  ) : null}
                </div>
              </li>
            ))}
          </ol>
        ) : (
          <p className="grid-empty">Chapters arriving soon.</p>
        )}

        <p className="book-foot">
          The book is in progress. Excerpts will publish here as chapters
          finalise — subscribe via the newsletter on the Research tab to be
          notified.
        </p>
      </div>
    </section>
  );
}

'use client';

import { useState, type FormEvent } from 'react';
import { Check, PaperPlaneTilt } from '@/components/icons';

/*
 * Newsletter signup on /documents#blogs — a night band ruled by gold
 * hairlines (styles in 13-documents-extras.css). Client-only because
 * it tracks submit state; not wired to a backend (the original was
 * also client-only — it just toggled button text on submit).
 */
export default function NewsletterForm() {
  const [subscribed, setSubscribed] = useState(false);
  const [email, setEmail] = useState('');

  function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (!email) return;
    // TODO: wire to /api/cms/submissions/newsletter once it exists.
    setSubscribed(true);
  }

  return (
    <div className="newsletter-card">
      <div>
        <div className="section-eyebrow newsletter-eyebrow">Newsletter</div>
        <h2 className="newsletter-title">Twice a month. <em>No spam.</em></h2>
        <p className="newsletter-body">
          Research summaries, new tools, and stories from the field — delivered in plain
          text, screen-reader-optimised, with a one-click unsubscribe.
        </p>
      </div>
      <form className="newsletter-form" onSubmit={handleSubmit}>
        <input
          type="email"
          placeholder="you@example.com"
          required
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          className="newsletter-input"
          aria-label="Email address"
          disabled={subscribed}
        />
        <button
          type="submit"
          className="btn-primary newsletter-btn"
          disabled={subscribed}
        >
          {subscribed ? (
            <><Check size="1em" aria-hidden="true" /> Subscribed</>
          ) : (
            <><PaperPlaneTilt size="1em" aria-hidden="true" /> Subscribe</>
          )}
        </button>
      </form>
    </div>
  );
}

/* ── DOCUMENTS — night-first editorial archive ─────────────────────
   Sight Beyond Sight §5: research as article rows, stories as an
   editorial block + rows, the Book tab as an actual book index.
   Gold hairlines structure the page; surfaces stay flat night. */

/* ── HERO ── */
.docs-hero {
  position: relative;
  overflow: hidden;
  padding: 96px var(--space-8) 72px;
  border-bottom: 1px solid var(--border);
  background: var(--bg);
}
.docs-hero-inner { max-width: var(--maxw); margin: 0 auto; position: relative; z-index: 1; }
.docs-hero-title {
  display: block;
  font-family: var(--font-display);
  font-size: clamp(2.4rem, 1.8rem + 2.6vw, 4rem);
  font-weight: 600;
  letter-spacing: -.015em;
  line-height: 1.05;
  color: var(--fg);
  margin: 0 0 20px;
  max-width: 22ch;
  text-wrap: balance;
}
.docs-hero-title em { color: var(--brand); font-style: italic; }
.docs-hero-sub { font-size: 1.1rem; color: var(--fg-muted); max-width: 62ch; line-height: 1.65; }

/* Echo-ripple motif — one decorative motif for this viewport. */
.docs-hero-ripple { position: absolute; inset: 0; pointer-events: none; }
.docs-hero-ripple span {
  position: absolute;
  top: 50%; right: -140px;
  transform: translate(0, -50%);
  border: 1px solid var(--brand);
  border-radius: 50%;
  opacity: .16;
  animation: docsRipple 6s ease-in-out infinite;
}
.docs-hero-ripple span:nth-child(1) { width: 260px; height: 260px; }
.docs-hero-ripple span:nth-child(2) { width: 440px; height: 440px; opacity: .11; animation-delay: .6s; }
.docs-hero-ripple span:nth-child(3) { width: 620px; height: 620px; opacity: .07; animation-delay: 1.2s; }
@keyframes docsRipple {
  0%, 100% { transform: translate(0, -50%) scale(1); }
  50% { transform: translate(0, -50%) scale(1.04); }
}
@media (prefers-reduced-motion: reduce) { .docs-hero-ripple span { animation: none; } }
[data-theme="high-contrast"] .docs-hero-ripple { display: none; }

/* ── RESEARCH / STORIES headings + filter ── */
.docs-research-heading, .docs-stories-heading { margin-bottom: var(--space-8); max-width: 720px; }
/* Topic pills come from the shared .filter-pill — bumped here to a
   ≥44px tap target on the archive. */
.docs-filter { margin-bottom: 8px; }
.docs-filter .filter-pill { padding: 11px 20px; min-height: 44px; }
.docs-filter .filter-label { color: var(--fg-muted); }

/* ── EDITORIAL ROWS (research papers + community stories) ── */
.doc-rows { border-top: 1px solid var(--brand); margin-top: 24px; }
.doc-row {
  display: grid;
  grid-template-columns: 176px minmax(0, 1fr) auto;
  gap: 28px;
  align-items: start;
  padding: 32px 4px;
  border-bottom: 1px solid var(--border);
  text-decoration: none;
  color: inherit;
  transition: background .2s, border-color .2s;
}
.doc-row:hover { background: var(--bg-elevated); border-bottom-color: var(--border-strong); }
.doc-row-side { display: flex; flex-direction: column; gap: 8px; padding-top: 6px; }
.doc-row-tag {
  font-family: var(--font-body);
  font-size: .72rem; font-weight: 700;
  letter-spacing: .14em; text-transform: uppercase;
  color: var(--brand);
}
.doc-row-date { font-size: .8rem; color: var(--fg-subtle); }
.doc-row-title {
  font-family: var(--font-display);
  font-size: clamp(1.3rem, 1.1rem + .9vw, 1.7rem);
  font-weight: 600;
  letter-spacing: -.015em;
  line-height: 1.2;
  color: var(--fg);
  margin: 0 0 10px;
  text-wrap: balance;
  display: block;
}
.doc-row-title em { color: var(--brand); font-style: italic; }
.doc-row:hover .doc-row-title { color: var(--brand); }
.doc-row-desc { font-size: .98rem; color: var(--fg-muted); line-height: 1.65; max-width: 68ch; margin: 0; }
.doc-row-meta { display: flex; align-items: center; gap: 10px; margin-top: 16px; flex-wrap: wrap; }
.doc-row-avatar {
  width: 32px; height: 32px; border-radius: 50%;
  display: inline-flex; align-items: center; justify-content: center;
  background: var(--brand-subtle);
  border: 1px solid var(--border-strong);
  font-family: var(--font-display);
  font-size: .72rem; font-weight: 700;
  color: var(--brand);
}
.doc-row-author { font-size: .86rem; font-weight: 600; color: var(--fg); }
.doc-row-role { font-weight: 500; color: var(--fg-subtle); }
.doc-row-read {
  margin-left: auto;
  font-family: var(--font-body);
  font-size: .78rem; font-weight: 700;
  letter-spacing: .06em;
  color: var(--brand);
  white-space: nowrap;
}
.doc-row-arrow {
  align-self: center;
  font-size: 1.35rem;
  color: var(--brand);
  transition: transform .2s;
}
.doc-row:hover .doc-row-arrow { transform: translateX(6px); }
@media (prefers-reduced-motion: reduce) {
  .doc-row-arrow, .doc-row { transition: none; }
}

/* Lead article (`extra: featured` from the CMS). */
.doc-row.featured { padding: 44px 4px; }
.doc-row.featured .doc-row-title { font-size: clamp(1.7rem, 1.3rem + 1.8vw, 2.5rem); }
.doc-row.featured .doc-row-desc { font-size: 1.05rem; }

@media (max-width: 820px) {
  .doc-row { grid-template-columns: minmax(0, 1fr); gap: 10px; padding: 26px 2px; }
  .doc-row-side { flex-direction: row; align-items: baseline; gap: 14px; padding-top: 0; }
  .doc-row-arrow { display: none; }
  .doc-row-read { margin-left: 0; width: 100%; }
}

/* ── BOOK TAB — the founder's memoir as a chapter index ── */
.book-intro { max-width: 760px; margin: 0 0 56px; }
.book-intro .section-eyebrow { margin-bottom: 16px; }
.book-title {
  display: block;
  font-family: var(--font-display);
  font-size: var(--text-title);
  font-weight: 600;
  letter-spacing: -.015em;
  line-height: 1.1;
  color: var(--fg);
  margin-bottom: 16px;
  text-wrap: balance;
}
.book-title em { color: var(--brand); font-style: italic; }
.book-byline {
  display: inline-flex; align-items: center; gap: 8px;
  font-family: var(--font-display); font-style: italic;
  font-size: 1.05rem; font-weight: 500;
  color: var(--brand);
  margin-bottom: 22px;
}
/* The intro reads as the book's opening page — larger, in Literata. */
.book-intro-text {
  font-family: var(--font-display);
  font-size: clamp(1.15rem, 1.05rem + .5vw, 1.35rem);
  font-weight: 400;
  line-height: 1.7;
  color: var(--fg-muted);
  max-width: 62ch;
}

.book-chapters {
  list-style: none; padding: 0; margin: 0;
  max-width: 860px;
  border-top: 1px solid var(--brand);
}
.book-chapter {
  display: grid;
  grid-template-columns: 120px minmax(0, 1fr);
  gap: 28px;
  padding: 40px 4px;
  border-bottom: 1px solid var(--border);
}
.book-chapter-num {
  font-family: var(--font-display);
  font-size: clamp(2.6rem, 2rem + 2.4vw, 4rem);
  font-weight: 300;
  font-variant-numeric: tabular-nums;
  line-height: .9;
  color: var(--brand);
}
.book-chapter-head {
  display: flex; align-items: baseline; gap: 18px; flex-wrap: wrap;
  margin-bottom: 12px;
}
.book-chapter-title {
  font-family: var(--font-display);
  font-style: italic;
  font-size: clamp(1.35rem, 1.2rem + .7vw, 1.7rem);
  font-weight: 600;
  letter-spacing: -.015em;
  line-height: 1.25;
  color: var(--fg);
  text-wrap: balance;
}
.book-chapter-readtime {
  display: inline-flex; align-items: center; gap: 6px;
  font-family: var(--font-body);
  font-size: .76rem; font-weight: 700;
  letter-spacing: .1em; text-transform: uppercase;
  color: var(--brand);
  white-space: nowrap;
}
.book-chapter-snippet {
  font-size: 1rem; line-height: 1.65; color: var(--fg-muted);
  max-width: 64ch; margin-bottom: 16px;
}
/* Quiet gold-dashed "Excerpt coming soon" state. */
.book-chapter-status {
  display: inline-block;
  font-family: var(--font-body);
  font-size: .72rem; font-weight: 700;
  letter-spacing: .1em; text-transform: uppercase;
  color: var(--brand);
  padding: 7px 14px;
  border: 1px dashed var(--brand);
  border-radius: var(--radius-full);
  background: transparent;
}
.book-foot {
  max-width: 860px; margin: 40px 0 0;
  font-size: .92rem; line-height: 1.65;
  color: var(--fg-subtle);
}
@media (max-width: 720px) {
  .book-chapter { grid-template-columns: minmax(0, 1fr); gap: 8px; padding: 30px 2px; }
  .book-chapter-num { font-size: 2.2rem; }
}

/* ── LEGACY CARD FAMILY ────────────────────────────────────────────
   .doc-grid/.doc-card are still consumed by the home page's
   StoryCard. Re-graded to the night language here (the old blue and
   orange gradients are gone); the documents archive itself now uses
   .doc-rows above. */
.doc-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 24px;
}
.doc-grid > .doc-card.featured { grid-column: span 2; }
@media (max-width: 720px) {
  .doc-grid > .doc-card.featured { grid-column: auto; }
}
.doc-card {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: border-color .2s, transform .2s;
  display: flex;
  flex-direction: column;
  min-width: 0; /* let the grid shrink this below intrinsic content */
  text-decoration: none;
  color: inherit;
}
.doc-card:hover { border-color: var(--border-strong); transform: translateY(-2px); }
@media (prefers-reduced-motion: reduce) { .doc-card { transition: none; } }
.doc-hero {
  aspect-ratio: 16/10;
  display: flex; align-items: flex-end;
  padding: 28px;
  position: relative; overflow: hidden; min-width: 0;
  border-bottom: 1px solid var(--border);
  color: var(--fg);
}
/* ponytail: StoryCard sets an inline background-image (with a dark
   bottom overlay) only when the CMS row has an image — [style] is the
   cheapest reliable hook for "photo present, use light text". */
.doc-hero[style] { color: #fff; }
.doc-card.featured .doc-hero { aspect-ratio: 16/9; }
.doc-card .cat-tag {
  font-family: var(--font-body);
  font-size: .7rem; font-weight: 700;
  letter-spacing: .12em; text-transform: uppercase;
  padding: 5px 12px;
  border-radius: var(--radius-full);
  align-self: flex-start; margin-bottom: 10px;
}
.doc-hero.type-blog,
.doc-hero.type-report,
.doc-hero.type-policy,
.doc-hero.type-tutorial { background: linear-gradient(160deg, var(--bg-subtle) 30%, var(--brand-subtle) 100%); }
.doc-hero.type-story,
.doc-hero.type-story2 { background: linear-gradient(160deg, var(--bg-subtle) 30%, var(--accent-subtle) 100%); }
.doc-hero h3 {
  font-family: var(--font-display);
  font-size: 1.35rem;
  font-weight: 600;
  line-height: 1.15;
  letter-spacing: -.015em;
  color: inherit;
  text-wrap: pretty;
  overflow-wrap: break-word;
  hyphens: auto;
}
.doc-card.featured .doc-hero h3 { font-size: 1.75rem; }
.doc-body { padding: 18px 22px 22px; display: flex; flex-direction: column; gap: 10px; flex: 1; min-width: 0; }
.doc-body p {
  font-size: .88rem;
  color: var(--fg-muted);
  line-height: 1.55;
  flex: 1;
  overflow-wrap: break-word;
  hyphens: auto;
}
.doc-meta { font-size: .75rem; color: var(--fg-subtle); font-family: var(--font-body); display: flex; gap: 10px; align-items: center; }
.doc-author { display: flex; align-items: center; gap: 8px; }
.doc-author .avatar { width: 22px; height: 22px; border-radius: 50%; background: var(--brand-subtle); border: 1px solid var(--border-strong); font-family: var(--font-display); font-weight: 700; font-size: .7rem; color: var(--brand); display: flex; align-items: center; justify-content: center; }

.cat-tag.blog, .cat-tag.report, .cat-tag.tutorial { background: var(--brand-subtle); color: var(--brand); }
.cat-tag.story, .cat-tag.policy { background: var(--accent-subtle); color: var(--accent); }
/* Over a photo the tinted chips vanish — keep them legible. */
.doc-hero[style] .cat-tag { background: rgba(0, 0, 0, .45); color: #fff; }
[data-theme="high-contrast"] .cat-tag.blog, [data-theme="high-contrast"] .cat-tag.report, [data-theme="high-contrast"] .cat-tag.tutorial,
[data-theme="high-contrast"] .cat-tag.story, [data-theme="high-contrast"] .cat-tag.policy { border: 1px solid var(--fg); }

/* Documents — newsletter band + featured-story editorial block
   (Sight Beyond Sight §5). */

/* ── NEWSLETTER BAND — night band ruled by gold hairlines ── */
.newsletter-band {
  background: var(--bg-subtle);
  border-top: 1px solid var(--brand);
  border-bottom: 1px solid var(--brand);
  padding: var(--space-16) var(--space-8);
}
.newsletter-band .section-inner { max-width: var(--maxw); margin: 0 auto; }
.newsletter-card {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 48px;
  align-items: center;
}
.newsletter-eyebrow { margin-bottom: 12px; }
.newsletter-title {
  font-family: var(--font-display);
  font-size: clamp(1.6rem, 1.3rem + 1.4vw, 2.35rem);
  font-weight: 600;
  color: var(--fg);
  margin-bottom: 12px;
  letter-spacing: -.015em;
  line-height: 1.12;
  text-wrap: balance;
}
.newsletter-title em { color: var(--brand); font-style: italic; }
.newsletter-body { color: var(--fg-muted); line-height: 1.65; max-width: 56ch; }
.newsletter-form { display: flex; flex-direction: column; gap: 12px; }
.newsletter-input {
  font-family: var(--font-body);
  font-size: 1rem;
  color: var(--fg);
  background: var(--bg);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-full);
  padding: 14px 22px;
  min-height: 48px;
  outline: none;
}
.newsletter-input::placeholder { color: var(--fg-subtle); }
.newsletter-input:focus { border-color: var(--brand); }
.newsletter-input:disabled { opacity: .6; }
.newsletter-btn { justify-content: center; min-height: 48px; }
.newsletter-btn:disabled { cursor: default; }

/* ── FEATURED STORY — the open call as a night editorial block ── */
.featured-story {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-top: 1px solid var(--brand);
  border-radius: var(--radius-lg);
  padding: clamp(28px, 5vw, 64px);
  margin-bottom: 64px;
}
.fs-eyebrow {
  font-family: var(--font-body);
  font-size: .72rem; font-weight: 700;
  letter-spacing: .16em; text-transform: uppercase;
  color: var(--brand);
  margin-bottom: 22px;
}
.fs-quote {
  display: block;
  font-family: var(--font-display);
  font-style: italic;
  font-size: clamp(1.5rem, 1.1rem + 2vw, 2.5rem);
  font-weight: 500;
  line-height: 1.22;
  letter-spacing: -.015em;
  color: var(--fg);
  max-width: 30ch;
  margin: 0 0 36px;
  text-wrap: balance;
}
.fs-quote::before { content: '\201C'; color: var(--brand); margin-right: .1em; }
.fs-body { border-top: 1px solid var(--border); padding-top: 32px; max-width: 780px; }
.fs-title {
  display: block;
  font-family: var(--font-display);
  font-size: clamp(1.3rem, 1.15rem + .8vw, 1.75rem);
  font-weight: 600;
  color: var(--fg);
  margin-bottom: 14px;
  letter-spacing: -.015em;
  line-height: 1.2;
  text-wrap: balance;
}
.fs-title em { color: var(--brand); font-style: italic; }
.fs-desc { color: var(--fg-muted); line-height: 1.7; margin-bottom: 28px; max-width: 68ch; }
.fs-author-row {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
}
.fs-author-avatar {
  width: 44px; height: 44px;
  border-radius: 50%;
  background: var(--brand-subtle);
  border: 1px solid var(--brand);
  color: var(--brand);
  display: flex; align-items: center; justify-content: center;
  font-family: var(--font-display);
  font-weight: 700;
  font-size: .85rem;
}
.fs-author-name {
  font-family: var(--font-body);
  font-weight: 700;
  font-size: .92rem;
  color: var(--fg);
}
.fs-author-role { font-size: .8rem; color: var(--fg-muted); }
.fs-read-btn { margin-left: auto; min-height: 48px; }

.stories-list-heading {
  font-family: var(--font-body);
  font-size: .8rem;
  font-weight: 700;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--fg-muted);
  margin-bottom: 4px;
}

@media (max-width: 720px) {
  .newsletter-card { grid-template-columns: 1fr; gap: 24px; }
  .fs-read-btn { margin-left: 0; width: 100%; justify-content: center; }
}
